package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one, but only while it is still DRAFT, OPEN or PENDING; a change another user
 *  made first is refused. Publishes the claim as stored. */
public class SaveProof {
    public void save(@Val Claim claim, ClaimRepository claims, SheetRepository sheets, Out<Claim> saved) throws InvalidClaimStatusException {
        if (!claims.addProof(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        saved.set(claims.find(claim.sheetId(), claim.id()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: who adds the proof. */
public class ValidateProof {
    public void validate(@RequestBody ProofRequest request, Out<ClaimProof> proof) {
        proof.set(new ClaimProof(request == null || request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

/** A proof added once its body is read: who adds it. */
public record ClaimProof(String by) {
}
package net.officefloor.hq.app.claim;

/** Body of adding a proof to a claim: who adds it. */
public record ProofRequest(String by) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Checks a proof may be added to the claim: not to a SETTLED or VOID claim, nor to one whose due-by falls inside a closed period.
 */
public class ApplyProof {
    public void apply(@Val Claim claim, PeriodRepository periods) throws InvalidClaimStatusException {
        if (claim.status() == ClaimStatus.SETTLED || claim.status() == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim takes no more proofs");
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_PROOF_ADDED to the audit file once the proof is stored, naming the claim (number=<number> when it has
 *  one) and ending with proofs=<count>. */
public class RecordClaimProofAdded {
    public void record(@Val Claim claim, @Val ClaimProof proof, PersonRepository people, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_PROOF_ADDED sheet=" + claim.sheetId() + " by=" + proof.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (claim.number() == null ? "" : " number=" + claim.number())
                + " proofs=" + claim.proofs());
    }
}
